package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose E.164 telephone is already used by an existing owner. Runs
 * after {@link NormalizeOwnerTelephone} has canonicalized the body's telephone, comparing it
 * against every stored owner's E.164 number so numbers that differ only in separators or an
 * assumed country code are still treated as duplicates.
 */
public class EnsureUniqueTelephone {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner owner : ownerRepository.findAll()) {
            if (Telephones.toE164(owner.getTelephone()).filter(telephone::equals).isPresent()) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}
===DuplicateTelephoneException===
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Thrown by {@link EnsureUniqueTelephone} when a create request's normalized telephone is
 * already used by an existing owner. Carries the normalized value for the handler's
 * message. Checked so it appears in the function's {@code throws} clause and routes to an
 * escalation.
 */
public class DuplicateTelephoneException extends Exception {

    private final String telephone;

    public DuplicateTelephoneException(String telephone) {
        super("Telephone already in use: " + telephone);
        this.telephone = telephone;
    }

    public String getTelephone() {
        return telephone;
    }
}
===Telephones===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Optional;

/**
 * Shared telephone handling: converts a raw number to its canonical E.164 form so numbers
 * written with different separators (or an explicit country code) compare equal. Used both
 * to normalize a create request before it is persisted and to compare it against existing
 * owners' stored numbers.
 */
final class Telephones {

    /** Country code assumed when the input carries no explicit '+' prefix (Australia). */
    private static final String DEFAULT_COUNTRY_CODE = "61";

    private Telephones() {
    }

    /**
     * Converts {@code telephone} to E.164 (a leading '+' followed by 8 to 15 digits).
     *
     * <p>Spaces, dashes and brackets are stripped. When the number keeps a leading '+' its
     * country code is preserved; otherwise {@code +61} is assumed and a single leading '0'
     * is dropped from the national digits. Returns empty when the result cannot form valid
     * E.164 (non-digits remain, or the digit count is out of range).
     */
    static Optional<String> toE164(String telephone) {
        if (telephone == null) {
            return Optional.empty();
        }
        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        }
        else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = DEFAULT_COUNTRY_CODE + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            return Optional.empty();
        }
        return Optional.of("+" + digits);
    }
}
